	/**
	 * A canonical-spine pass can retain the same executable fallback at the same saturated cost while its child winners
	 * and physical metadata have advanced. That is a refresh of one physical identity, not a competing plan.
	 */
	private boolean refreshesSameExecutableFallback(int winnerId, int comparisonTier, int physicalExpressionId,
			int physicalMetadataId, int tieBreakRank, double startupCost, double totalCost, double comparisonCost,
			double peakMemoryRows, int[] candidateChildren, int childOffset, int childCount) {
		if (comparisonTier != EXECUTABLE_FALLBACK
				|| comparisonTiers[winnerId] != EXECUTABLE_FALLBACK
				|| physicalExpressionId != physicalExpressionIds[winnerId]
				|| tieBreakRank != tieBreakRanks[winnerId]
				|| Double.compare(startupCost, startupCosts[winnerId]) != 0
				|| Double.compare(totalCost, totalCosts[winnerId]) != 0
				|| Double.compare(comparisonCost, comparisonCosts[winnerId]) != 0
				|| Double.compare(peakMemoryRows, this.peakMemoryRows[winnerId]) != 0) {
			return false;
		}
		if (physicalMetadataId != physicalMetadataIds[winnerId] || childCount != childCounts[winnerId]) {
			return true;
		}
		int currentChildStart = childStarts[winnerId];
		for (int ordinal = 0; ordinal < childCount; ordinal++) {
			if (candidateChildren[childOffset + ordinal] != childWinnerIds[currentChildStart + ordinal]) {
				return true;
			}
		}
		return false;
	}

	private boolean candidateIsBetter(int winnerId, int comparisonTier, int physicalExpressionId, int tieBreakRank,
			double startupCost, double totalCost, double comparisonCost, double peakMemoryRows) {
		int comparison = Integer.compare(comparisonTier, comparisonTiers[winnerId]);
		if (comparison != 0) {
			return comparison < 0;
		}
		comparison = Double.compare(totalCost, totalCosts[winnerId]);
		if (comparison != 0) {
			return comparison < 0;
		}
		comparison = Double.compare(comparisonCost, comparisonCosts[winnerId]);
		if (comparison != 0) {
			return comparison < 0;
		}
		comparison = Double.compare(startupCost, startupCosts[winnerId]);
		if (comparison != 0) {
			return comparison < 0;
		}
		comparison = Double.compare(peakMemoryRows, this.peakMemoryRows[winnerId]);
		if (comparison != 0) {
			return comparison < 0;
		}
		comparison = Integer.compare(originalPlanPreference(tieBreakRank),
				originalPlanPreference(tieBreakRanks[winnerId]));
		if (comparison != 0) {
			return comparison < 0;
		}
		comparison = Integer.compare(physicalExpressionId, physicalExpressionIds[winnerId]);
		return comparison < 0;
	}

	private static int originalPlanPreference(int tieBreakRank) {
		return tieBreakRank == 0 ? 0 : 1;
	}

	private void writeCandidate(int winnerId, int comparisonTier, int physicalExpressionId, int physicalMetadataId,
			int tieBreakRank, double startupCost, double totalCost, double comparisonCost, double peakMemoryRows,
			int[] candidateChildren, int childOffset, int childCount) {
		physicalExpressionIds[winnerId] = physicalExpressionId;
		physicalMetadataIds[winnerId] = physicalMetadataId;
		startupCosts[winnerId] = startupCost;
		totalCosts[winnerId] = totalCost;
		comparisonCosts[winnerId] = comparisonCost;
		this.peakMemoryRows[winnerId] = peakMemoryRows;
		comparisonTiers[winnerId] = (byte) comparisonTier;
		tieBreakRanks[winnerId] = tieBreakRank;
		childStarts[winnerId] = childSize;
		childCounts[winnerId] = childCount;
		if (childCount > 0) {
			ensureChildCapacity(childSize + childCount);
			System.arraycopy(candidateChildren, childOffset, childWinnerIds, childSize, childCount);
			childSize += childCount;
		}
	}

	private int findAdditionalSlot(long hash, int groupId, int requiredPropertyId, int semanticRowGoalId,
			int inputContextId, int costPolicyId) {
		int slot = PackedPrimitiveHash.slot(hash, additionalTableSlots.length);
		while (true) {
			int winnerId = additionalTableSlots[slot];
			if (winnerId == 0 || hashes[winnerId] == hash && keyEquals(winnerId, groupId, requiredPropertyId,
					semanticRowGoalId, inputContextId, costPolicyId)) {
				return slot;
			}
			slot = (slot + 1) & (additionalTableSlots.length - 1);
		}
	}

	private boolean keyEquals(int winnerId, int groupId, int requiredPropertyId, int semanticRowGoalId,
			int inputContextId, int costPolicyId) {
		return groupIds[winnerId] == groupId
				&& requiredPropertyIds[winnerId] == requiredPropertyId
				&& semanticRowGoalIds[winnerId] == semanticRowGoalId
				&& inputContextIds[winnerId] == inputContextId
				&& costPolicyIds[winnerId] == costPolicyId;
	}

	private void resizeAdditionalTable(int newCapacity) {
		int[] replacement = new int[newCapacity];
		for (int oldSlot = 0; oldSlot < additionalTableSlots.length; oldSlot++) {
			int winnerId = additionalTableSlots[oldSlot];
			if (winnerId == 0) {
				continue;
			}
			int newSlot = PackedPrimitiveHash.slot(hashes[winnerId], newCapacity);
			while (replacement[newSlot] != 0) {
				newSlot = (newSlot + 1) & (newCapacity - 1);
			}
			replacement[newSlot] = winnerId;
		}
		additionalTableSlots = replacement;
		additionalResizeThreshold = PackedPrimitiveHash.maximumFill(newCapacity);
	}

	private void ensureDefaultGroupCapacity(int groupId) {
		if (groupId < defaultWinnerByGroup.length) {
			return;
		}
		int newCapacity = defaultWinnerByGroup.length;
		while (newCapacity <= groupId) {
			newCapacity <<= 1;
		}
		defaultWinnerByGroup = Arrays.copyOf(defaultWinnerByGroup, newCapacity);
	}

	private void ensureRowCapacity(int requiredWinnerId) {
		if (requiredWinnerId < hashes.length) {
			return;
		}
		int newCapacity = hashes.length << 1;
		groupIds = Arrays.copyOf(groupIds, newCapacity);
		requiredPropertyIds = Arrays.copyOf(requiredPropertyIds, newCapacity);
		semanticRowGoalIds = Arrays.copyOf(semanticRowGoalIds, newCapacity);
		inputContextIds = Arrays.copyOf(inputContextIds, newCapacity);
		costPolicyIds = Arrays.copyOf(costPolicyIds, newCapacity);
		hashes = Arrays.copyOf(hashes, newCapacity);
		physicalExpressionIds = Arrays.copyOf(physicalExpressionIds, newCapacity);
		physicalMetadataIds = Arrays.copyOf(physicalMetadataIds, newCapacity);
		startupCosts = Arrays.copyOf(startupCosts, newCapacity);
		totalCosts = Arrays.copyOf(totalCosts, newCapacity);
		comparisonCosts = Arrays.copyOf(comparisonCosts, newCapacity);
		peakMemoryRows = Arrays.copyOf(peakMemoryRows, newCapacity);
		comparisonTiers = Arrays.copyOf(comparisonTiers, newCapacity);
		tieBreakRanks = Arrays.copyOf(tieBreakRanks, newCapacity);
		childStarts = Arrays.copyOf(childStarts, newCapacity);
		childCounts = Arrays.copyOf(childCounts, newCapacity);
	}

	private void ensureChildCapacity(int requiredSize) {
		if (requiredSize <= childWinnerIds.length) {
			return;
		}
		int newCapacity = childWinnerIds.length;
		while (newCapacity < requiredSize) {
			newCapacity <<= 1;
		}
		childWinnerIds = Arrays.copyOf(childWinnerIds, newCapacity);
	}

	private boolean isDefaultGoal(int requiredPropertyId, int semanticRowGoalId, int inputContextId,
			int costPolicyId) {
		return requiredPropertyId == defaultPropertyId
				&& semanticRowGoalId == 0
				&& inputContextId == 0
				&& costPolicyId == 0;
	}

	private static long hash(int groupId, int requiredPropertyId, int semanticRowGoalId, int inputContextId,
			int costPolicyId) {
		long hash = PackedPrimitiveHash.step(PackedPrimitiveHash.SEED, groupId);
		hash = PackedPrimitiveHash.step(hash, requiredPropertyId);
		hash = PackedPrimitiveHash.step(hash, semanticRowGoalId);
		hash = PackedPrimitiveHash.step(hash, inputContextId);
		return PackedPrimitiveHash.finish(PackedPrimitiveHash.step(hash, costPolicyId));
	}

	private static void checkCandidate(int groupId, int requiredPropertyId, int semanticRowGoalId,
			int inputContextId, int costPolicyId, int comparisonTier, int physicalExpressionId, int tieBreakRank,
			double startupCost, double totalCost, double comparisonCost, double peakMemoryRows, int[] children,
			int childOffset, int childCount) {
		checkGoal(groupId, requiredPropertyId, semanticRowGoalId, inputContextId, costPolicyId);
		if (comparisonTier != COSTED && comparisonTier != EXECUTABLE_FALLBACK) {
			throw new IllegalArgumentException("unknown winner comparison tier");
		}
		if (physicalExpressionId <= 0) {
			throw new IllegalArgumentException("physical expression id must be positive");
		}
		if (tieBreakRank < 0) {
			throw new IllegalArgumentException("winner tie-break rank must not be negative");
		}
		if (!Double.isFinite(startupCost) || !Double.isFinite(totalCost) || !Double.isFinite(comparisonCost)
				|| !Double.isFinite(peakMemoryRows) || peakMemoryRows < 0.0d) {
			throw new IllegalArgumentException("winner costs must be finite");
		}
		if (children == null || childOffset < 0 || childCount < 0 || childOffset > children.length - childCount) {
			throw new IndexOutOfBoundsException("invalid child-winner slice");
		}
	}

	private static void checkGoal(int groupId, int requiredPropertyId, int semanticRowGoalId, int inputContextId,
			int costPolicyId) {
		if (groupId <= 0 || requiredPropertyId <= 0 || semanticRowGoalId < 0 || inputContextId < 0
				|| costPolicyId < 0) {
			throw new IllegalArgumentException("invalid winner key");
		}
	}

	private void checkWinnerId(int winnerId) {
		if (winnerId <= 0 || winnerId > size) {
			throw new IndexOutOfBoundsException("unknown winner " + winnerId);
		}
	}

	private static double saturatedAdd(double left, double right) {
		double sum = left + right;
		return Double.isFinite(sum) ? sum : Double.MAX_VALUE;
	}
